using System.Text.Json;
using System.Text.Json.Nodes;
using SuperUI.Themes;

namespace ThemeDarkGenerator;

/// <summary>
/// One-shot tool: reads each "Modern" theme JSON in SuperUI/Themes/json/ and injects
/// a "dark" block generated by the brand-consistent triadic +120° pattern
/// (or the canonical palette for the 3 special themes).
///
/// 17 themes — auto-derived (H_dark = (H_light + 120) mod 360).
/// 3 themes  — hand-tuned canonical palettes (Dracula, Gruvbox, Catppuccin).
///
/// Idempotent: skips themes that already have a "dark" block.
/// </summary>
public static class Program
{
    private const string ThemesDir = @"C:\Users\SuperComp\Documents\Blazor\SuperUI.Blazor\SuperUI\Themes\json";

    // 3 special themes: id → (display name, primary hue, base bg, base fg, primary default)
    private static readonly Dictionary<string, (string name, double hue, string bg, string fg, string primary)> Specials = new()
    {
        ["dracula-dusk"] = ("Dracula Dusk",   290, "oklch(0.22 0.02 290)",   "oklch(0.93 0.015 290)",  "oklch(0.70 0.18 290)"),
        ["gruvbox-amber"] = ("Gruvbox Amber",  50, "oklch(0.18 0.015 50)",   "oklch(0.90 0.04 70)",    "oklch(0.78 0.16 65)"),
        ["catppuccin-mocha"] = ("Catppuccin Mocha", 280, "oklch(0.18 0.02 280)", "oklch(0.88 0.04 280)", "oklch(0.74 0.13 320)"),
    };

    public static int Main()
    {
        var files = Directory.GetFiles(ThemesDir, "*.json")
            .Where(f => IsModernTheme(f))
            .OrderBy(f => Path.GetFileName(f))
            .ToArray();

        Console.WriteLine($"Found {files.Length} Modern theme files.\n");

        var autoCount = 0;
        var specialCount = 0;
        var skippedCount = 0;

        foreach (var file in files)
        {
            var id = Path.GetFileNameWithoutExtension(file);

            // Parse JSON.
            var text = File.ReadAllText(file);
            var root = JsonNode.Parse(text)!;

            // Skip if dark block already exists.
            if (root["dark"] != null)
            {
                Console.WriteLine($"  [skip]  {id,-25} already has dark block");
                skippedCount++;
                continue;
            }

            // Extract light hue from "primitives.primary.N500" (e.g., "oklch(0.55 0.22 153)").
            var lightHue = ExtractPrimaryHue(root);
            if (lightHue == null)
            {
                Console.WriteLine($"  [ERROR] {id,-25} could not extract primary hue");
                continue;
            }

            // Build dark block.
            JsonObject dark;
            if (Specials.TryGetValue(id, out var spec))
            {
                dark = BuildSpecialDark(root, spec);
                specialCount++;
                Console.WriteLine($"  [special] {id,-25} lightH={lightHue,5:F1}  canonical palette");
            }
            else
            {
                var darkHue = (lightHue.Value + 120) % 360;
                dark = BuildAutoDark(root, darkHue);
                autoCount++;
                Console.WriteLine($"  [auto]    {id,-25} lightH={lightHue,5:F1} → darkH={darkHue,5:F1}");
            }

            root["dark"] = dark;

            // Write back with 2-space indent.
            var options = new JsonSerializerOptions { WriteIndented = true };
            File.WriteAllText(file, root.ToJsonString(options) + "\n");
        }

        Console.WriteLine();
        Console.WriteLine($"Done. Auto: {autoCount}  Special: {specialCount}  Skipped: {skippedCount}");
        return 0;
    }

    private static bool IsModernTheme(string filePath)
    {
        try
        {
            var text = File.ReadAllText(filePath);
            return text.Contains("\"category\": \"Modern\"");
        }
        catch
        {
            return false;
        }
    }

    private static double? ExtractPrimaryHue(JsonNode root)
    {
        // Try primitives.primary.500
        var n500 = root["primitives"]?["primary"]?["500"]?.GetValue<string>();
        if (n500 != null) return ParseHue(n500);

        // Fall back to primitives.Primary500 (uppercase variant)
        n500 = root["primitives"]?["Primary500"]?.GetValue<string>();
        if (n500 != null) return ParseHue(n500);

        return null;
    }

    private static double? ParseHue(string oklch)
    {
        // oklch(L C H) — extract last number
        var match = System.Text.RegularExpressions.Regex.Match(oklch, @"oklch\(\s*[\d.]+\s+[\d.]+\s+([\d.]+)");
        if (match.Success && double.TryParse(match.Groups[1].Value, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out var h))
            return h;
        return null;
    }

    private static JsonObject BuildAutoDark(JsonNode root, double darkHue)
