                ["muted"]      = $"oklch(0.18 0.012 {H})",
                ["emphasized"] = $"oklch(0.22 0.014 {H})",
                ["overlay"]    = "oklch(0 0 0 / 0.72)",
                ["glass"]      = $"oklch(0.11 0.008 {H} / 0.7)"
            },
            ["surface"] = new JsonObject
            {
                ["default"] = $"oklch(0.16 0.012 {H})",
                ["raised"]  = $"oklch(0.20 0.014 {H})",
                ["overlay"] = $"oklch(0.24 0.016 {H})"
            },
            ["fg"] = new JsonObject
            {
                ["default"]   = $"oklch(0.95 0.005 {H})",
                ["subtle"]    = $"oklch(0.82 0.008 {H})",
                ["muted"]     = $"oklch(0.65 0.010 {H})",
                ["disabled"]  = $"oklch(0.55 0.010 {H})",
                ["inverse"]   = $"oklch(0.11 0.008 {H})",
                ["link"]      = $"oklch(0.65 0.20 {H})",
                ["linkHover"] = $"oklch(0.70 0.18 {H})"
            },
            ["border"] = new JsonObject
            {
                ["default"] = $"oklch(0.25 0.016 {H})",
                ["subtle"]  = $"oklch(0.18 0.012 {H})",
                ["strong"]  = $"oklch(0.32 0.018 {H})",
                ["focus"]   = $"oklch(0.65 0.20 {H})"
            },
            ["divider"] = $"oklch(0.18 0.012 {H})",
            ["colorPrimary"] = new JsonObject
            {
                ["default"] = $"oklch(0.65 0.22 {H})",
                ["subtle"]  = $"oklch(0.22 0.06 {H})",
                ["hover"]   = $"oklch(0.70 0.22 {H})",
                ["fg"]      = $"oklch(0.11 0.008 {H})"
            },
            ["colorSuccess"] = new JsonObject
            {
                ["default"] = "oklch(0.65 0.18 153)",
                ["subtle"]  = "oklch(0.22 0.05 153)",
                ["hover"]   = "oklch(0.70 0.18 153)",
                ["fg"]      = "oklch(0.11 0.008 " + H + ")"
            },
            ["colorDanger"] = new JsonObject
            {
                ["default"] = "oklch(0.62 0.22 19)",
                ["subtle"]  = "oklch(0.24 0.06 19)",
                ["hover"]   = "oklch(0.68 0.22 19)",
                ["fg"]      = "oklch(0.11 0.008 " + H + ")"
            },
            ["colorWarning"] = new JsonObject
            {
                ["default"] = "oklch(0.74 0.16 75)",
                ["subtle"]  = "oklch(0.26 0.05 75)",
                ["hover"]   = "oklch(0.80 0.14 75)",
                ["fg"]      = $"oklch(0.11 0.008 {H})"
            },
            ["colorInfo"] = new JsonObject
            {
                ["default"] = "oklch(0.62 0.15 254)",
                ["subtle"]  = "oklch(0.22 0.05 254)",
                ["hover"]   = "oklch(0.68 0.14 254)",
                ["fg"]      = "oklch(0.11 0.008 " + H + ")"
            },
            ["font"] = DeepClone(root["light"]?["font"]) ?? new JsonObject
            {
                ["default"] = "'Inter', system-ui, -apple-system, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif",
                ["mono"]    = "'JetBrains Mono', ui-monospace, monospace"
            },
            ["text"]       = DeepClone(root["light"]?["text"])!,
            ["fontWeight"] = DeepClone(root["light"]?["fontWeight"])!,
            ["lineHeight"] = DeepClone(root["light"]?["lineHeight"])!,
            ["shadow"] = new JsonObject
            {
                ["xs"] = "0 1px 2px 0 oklch(0 0 0 / 0.40)",
                ["sm"] = "0 2px 4px -1px oklch(0 0 0 / 0.50)",
                ["md"] = "0 4px 12px -2px oklch(0 0 0 / 0.55)",
                ["lg"] = "0 8px 24px -4px oklch(0 0 0 / 0.60)",
                ["xl"] = "0 16px 48px -8px oklch(0 0 0 / 0.65)"
            },
            ["radius"]     = DeepClone(root["light"]?["radius"])!,
            ["transition"] = DeepClone(root["light"]?["transition"])!,
            ["focusRing"]  = DeepClone(root["light"]?["focusRing"])!,
            ["z"]          = DeepClone(root["light"]?["z"])!
