        return dark;
    }

    private static JsonObject BuildSpecialDark(JsonNode root, (string name, double hue, string bg, string fg, string primary) spec)
    {
        var H = spec.hue.ToString("0.##", System.Globalization.CultureInfo.InvariantCulture);

        // For special themes, dark is the canonical dark palette.
        // Hue is used for color* default/subtle/hover consistency.
        var dark = new JsonObject
        {
            ["bg"] = new JsonObject
            {
                ["default"]    = spec.bg,                                // canonical dark bg
                ["subtle"]     = AdjustL(spec.bg, 0.04),
                ["muted"]      = AdjustL(spec.bg, 0.07),
                ["emphasized"] = AdjustL(spec.bg, 0.11),
                ["overlay"]    = "oklch(0 0 0 / 0.78)",
                ["glass"]      = AdjustA(spec.bg, 0.7)
            },
            ["surface"] = new JsonObject
            {
                ["default"] = AdjustL(spec.bg, 0.04),
                ["raised"]  = AdjustL(spec.bg, 0.08),
                ["overlay"] = AdjustL(spec.bg, 0.12)
            },
            ["fg"] = new JsonObject
            {
                ["default"]   = spec.fg,
                ["subtle"]    = AdjustL(spec.fg, -0.13),
                ["muted"]     = AdjustL(spec.fg, -0.27),
                ["disabled"]  = AdjustL(spec.fg, -0.40),
                ["inverse"]   = spec.bg,
                ["link"]      = AdjustC(spec.primary, 0.05),
                ["linkHover"] = AdjustL(spec.primary, 0.06)
            },
            ["border"] = new JsonObject
            {
                ["default"] = AdjustL(spec.bg, 0.14),
                ["subtle"]  = AdjustL(spec.bg, 0.07),
                ["strong"]  = AdjustL(spec.bg, 0.21),
                ["focus"]   = spec.primary
            },
            ["divider"] = AdjustL(spec.bg, 0.07),
            ["colorPrimary"] = new JsonObject
            {
                ["default"] = spec.primary,
                ["subtle"]  = AdjustL(spec.bg, 0.10, spec.hue, 0.10),
                ["hover"]   = AdjustL(spec.primary, 0.06),
                ["fg"]      = spec.bg
            },
            ["colorSuccess"] = SpecialColor(153),
            ["colorDanger"]  = SpecialColor(19),
            ["colorWarning"] = SpecialColor(75),
            ["colorInfo"]    = SpecialColor(254),
            ["font"] = DeepClone(root["light"]?["font"]) ?? new JsonObject(),
            ["text"]       = DeepClone(root["light"]?["text"])!,
            ["fontWeight"] = DeepClone(root["light"]?["fontWeight"])!,
            ["lineHeight"] = DeepClone(root["light"]?["lineHeight"])!,
            ["shadow"] = new JsonObject
            {
                ["xs"] = "0 1px 2px 0 oklch(0 0 0 / 0.50)",
                ["sm"] = "0 2px 4px -1px oklch(0 0 0 / 0.60)",
                ["md"] = "0 4px 12px -2px oklch(0 0 0 / 0.65)",
                ["lg"] = "0 8px 24px -4px oklch(0 0 0 / 0.70)",
                ["xl"] = "0 16px 48px -8px oklch(0 0 0 / 0.75)"
            },
            ["radius"]     = DeepClone(root["light"]?["radius"])!,
            ["transition"] = DeepClone(root["light"]?["transition"])!,
            ["focusRing"]  = DeepClone(root["light"]?["focusRing"])!,
            ["z"]          = DeepClone(root["light"]?["z"])!
        };

        return dark;
    }

    private static JsonObject SpecialColor(double hue)
    {
        // Generic darker-mode semantic colors at the same hue.
        return new JsonObject
        {
            ["default"] = $"oklch(0.70 0.18 {hue})",
            ["subtle"]  = $"oklch(0.25 0.06 {hue})",
            ["hover"]   = $"oklch(0.76 0.18 {hue})",
            ["fg"]      = $"oklch(0.95 0.005 {hue})"
        };
    }

    private static string AdjustL(string oklch, double deltaL)
    {
        // oklch(L C H[/A]) → oklch(L+deltaL C H)
        var m = System.Text.RegularExpressions.Regex.Match(oklch, @"oklch\(\s*([\d.]+)\s+([\d.]+)\s+([\d.]+)(\s*/\s*[\d.]+)?\s*\)");
        if (!m.Success) return oklch;
        var L = double.Parse(m.Groups[1].Value, System.Globalization.CultureInfo.InvariantCulture) + deltaL;
        var C = m.Groups[2].Value;
        var H = m.Groups[3].Value;
        var A = m.Groups[4].Success ? m.Groups[4].Value : "";
        return FormOklch(L, double.Parse(C, System.Globalization.CultureInfo.InvariantCulture), double.Parse(H, System.Globalization.CultureInfo.InvariantCulture), A);
    }

    private static string AdjustL(string oklch, double deltaL, double injectHue, double injectC)
    {
        var m = System.Text.RegularExpressions.Regex.Match(oklch, @"oklch\(\s*([\d.]+)\s+([\d.]+)\s+([\d.]+)(\s*/\s*[\d.]+)?\s*\)");
        if (!m.Success) return oklch;
        var L = double.Parse(m.Groups[1].Value, System.Globalization.CultureInfo.InvariantCulture) + deltaL;
        return FormOklch(L, injectC, injectHue, "");
    }

    private static string AdjustC(string oklch, double deltaC)
    {
        var m = System.Text.RegularExpressions.Regex.Match(oklch, @"oklch\(\s*([\d.]+)\s+([\d.]+)\s+([\d.]+)");
        if (!m.Success) return oklch;
        var C = double.Parse(m.Groups[2].Value, System.Globalization.CultureInfo.InvariantCulture) + deltaC;
        return FormOklch(double.Parse(m.Groups[1].Value, System.Globalization.CultureInfo.InvariantCulture), C, double.Parse(m.Groups[3].Value, System.Globalization.CultureInfo.InvariantCulture), "");
    }

    private static string FormOklch(double L, double C, double H, string alphaPart)
    {
        var inv = System.Globalization.CultureInfo.InvariantCulture;
        var s = $"oklch({L.ToString("0.###", inv)} {C.ToString("0.###", inv)} {H.ToString("0.##", inv)}{alphaPart})";
        return s;
    }

    private static string AdjustA(string oklch, double alpha)
    {
        var m = System.Text.RegularExpressions.Regex.Match(oklch, @"oklch\(\s*([\d.]+)\s+([\d.]+)\s+([\d.]+)(\s*/\s*[\d.]+)?\s*\)");
        if (!m.Success) return oklch;
        var L = m.Groups[1].Value;
        var C = m.Groups[2].Value;
        var H = m.Groups[3].Value;
        var inv = System.Globalization.CultureInfo.InvariantCulture;
        return $"oklch({L} {C} {H} / {alpha.ToString("0.##", inv)})";
    }

    private static JsonNode? DeepClone(JsonNode? source)
    {
        if (source == null) return null;
        return JsonNode.Parse(source.ToJsonString());
    }
}
